    [FormEventHandler(formStr(ProjProjectsListPage), FormEventType::Initialized)]
    public static void metInit_OnInitialized(xFormRun sender, FormEventArgs e)
    {
        ProjTable       projTable;
        Query       metQuery = new Query(queryStr(ProjTableInPlanning));

        if (sender.args().menuItemName() == menuItemDisplayStr(ProjTableInPlanning))
        {
            //Pretending to pass a record to bypass the filter logic in the ProjTableListPage form lines 63 to 65. This
            //filter is overriding all the status filter applied before.
            sender.args().record(projTable);
        }

    }
